src/checkout/capture.js.text:
// Takes the payment of an order through the gateway. Called by the pay button (src/ui/pay-button.js).
// A second call for the same order while the first is still running gets the first call's result:
// the button can be pressed twice before the page re-renders, and a customer must never be charged twice (issue #43).
export function createCapture(gateway) {
  const running = new Map();

  async function charge(order) {
    const receipt = await gateway.charge(order.id, order.total);
    order.paid = true;
    order.receipt = receipt;
    return receipt;
  }

  return async function capture(order) {
    if (order.paid) return order.receipt;
    if (!running.has(order.id)) {
      // A failed charge is forgotten too, so that the payment can be tried again.
      running.set(order.id, charge(order).finally(() => running.delete(order.id)));
    }
    return running.get(order.id);
  };
}

src/gateway.js.text:
// The payment gateway's sandbox, used in development and in the tests. Every charge is kept in `charges`.
// A charge takes a little time, as the real gateway does.
export function createSandboxGateway({ delayMs = 5 } = {}) {
  const charges = [];
  return {
    charges,
    async charge(orderId, amount) {
      await new Promise((resolve) => setTimeout(resolve, delayMs));
      const receipt = { id: `ch_${charges.length + 1}`, orderId, amount };
      charges.push(receipt);
      return receipt;
    },
  };
}

src/receipts.js.text:
// The receipt line shown after a payment. Prices include 10% tax; the tax part is shown too.
export const TAX_RATE = 0.1;

export function formatReceipt(receipt) {
  const tax = Math.round((receipt.amount * TAX_RATE) / (1 + TAX_RATE));
  return `Receipt ${receipt.id}: ${receipt.amount.toLocaleString('en-US')} yen (tax ${tax.toLocaleString('en-US')} yen included)`;
}

